solution:
def bounce(x, dx, width):
    nx = x + dx
    if nx < 0 or nx > width - 1:
        dx = -dx
        nx = x + dx
    return nx, dx

alt:
def bounce(x, dx, width):
    if not 0 <= x + dx < width:
        dx = -dx
    return x + dx, dx
